class TinyGPT:
    def __init__(self):
        # Map each word -> {next_word: count}
        self.bigrams = {}

    def train(self, text: str):
        words = text.lower().split()
        for a, b in zip(words, words[1:]):
            nxt = self.bigrams.setdefault(a, {})
            nxt[b] = nxt.get(b, 0) + 1

    def predict_next(self, word: str):
        nxt = self.bigrams.get(word)
        if not nxt:
            return None
        best = None
        best_count = 0
        for w, c in nxt.items():  # dicts keep insertion order -> ties go to first seen
            if c > best_count:
                best, best_count = w, c
        return best

    def generate(self, start_word: str, n: int = 5) -> list:
        result = [start_word]
        while len(result) < n:
            nxt = self.predict_next(result[-1])
            if nxt is None:
                break
            result.append(nxt)
        return result


# Test it:
gpt = TinyGPT()
gpt.train("the cat sat on the mat the cat ran")

print(gpt.predict_next("the"))   # 'cat' (appears most after 'the')
print(gpt.predict_next("cat"))   # 'sat' or 'ran' (tie -> first seen)
print(gpt.predict_next("zebra")) # None
print(gpt.generate("the", 4))

import math

class Sampler:
    def greedy(self, scores: dict) -> str:
        return max(scores, key=lambda t: scores[t])

    def top_k(self, scores: dict, k: int) -> list:
        ranked = sorted(scores, key=lambda t: scores[t], reverse=True)
        return ranked[:max(k, 0)]

    def softmax(self, scores: dict) -> dict:
        if not scores:
            return {}
        m = max(scores.values())
        exps = {t: math.exp(s - m) for t, s in scores.items()}
        total = sum(exps.values())
        return {t: e / total for t, e in exps.items()}

# Test it:
s = Sampler()
logits = {"Paris": 5.0, "London": 2.0, "Rome": 3.0, "cat": -1.0}

print(s.greedy(logits))         # 'Paris'
print(s.top_k(logits, 2))       # ['Paris', 'Rome']
probs = s.softmax(logits)
print(round(sum(probs.values()), 5))  # 1.0
print(s.greedy(probs) == "Paris")     # True
